const detailArticle=(item,context='')=>`<article class="news-highlight ${esc(item.tone||'neutral')}"><div class="news-title"><span class="tag ${esc(item.tone||'neutral')}">${esc(item.impactLabel||item.importance||'Bilgi')}</span><a href="${detailUrl(item.url)}" target="_blank" rel="noopener">${esc(item.title)} ↗</a></div><small>${context?esc(context)+(Number.isFinite(item.holdingWeight)?' · fon ağırlığı '+pct(item.holdingWeight):'')+' · ':''}${esc(item.publisher||'Yayıncı')} · ${stamp(item.date)}</small><span class="news-impact-meta">${esc(item.impactReason||'Başlıkta doğrulanabilir yön bulunamadı')} · ${context?'ETF üzerindeki etki dolaylıdır · ':''}Başlığa dayalı ön sınıflama</span></article>`;
const articleList=(items,initial=8)=>items.slice(0,initial).map(x=>detailArticle(x,x.relatedTo||'')).join('')+(items.length>initial?`<details class="news-more"><summary>${items.length-initial} haber daha göster</summary>${items.slice(initial).map(x=>detailArticle(x,x.relatedTo||'')).join('')}</details>`:'');
function etfRisk(s){
 const prices=(s.history||[]).map(x=>x.close).filter(Number.isFinite),returns=prices.slice(1).map((p,i)=>p/prices[i]-1),n=returns.length;
 if(n<20)return {sharpe:null,sortino:null,calmar:null,var95:null,annual:null,medianVolume:null};
 const mean=returns.reduce((a,b)=>a+b,0)/n,variance=returns.reduce((a,b)=>a+(b-mean)**2,0)/(n-1),vol=Math.sqrt(variance)*Math.sqrt(252),negative=returns.filter(x=>x<0),downside=Math.sqrt(negative.reduce((a,b)=>a+b*b,0)/n)*Math.sqrt(252),annual=(prices.at(-1)/prices[0])**(252/n)-1;
 const sorted=[...returns].sort((a,b)=>a-b),volumes=(s.history||[]).slice(-20).map(x=>x.volume).filter(Number.isFinite).sort((a,b)=>a-b);
 return {sharpe:vol?mean*252/vol:null,sortino:downside?mean*252/downside:null,calmar:s.analysis.maxDrawdown<0?annual/Math.abs(s.analysis.maxDrawdown/100):null,var95:sorted[Math.floor(n*.05)]*100,annual:annual*100,medianVolume:volumes.length?volumes[Math.floor(volumes.length/2)]:null};
}
function etfAssessment(s,profile){
 const a=s.analysis||{},checks=[];
 const add=(name,value,tone,why)=>checks.push({name,value,tone,why});
 if(Number.isFinite(a.return1y))add('1 yıllık getiri',pct(a.return1y),a.return1y>10?'positive':a.return1y< -10?'negative':'neutral','Son 252 işlem günlük fiyat getirisi.');
 if(Number.isFinite(a.reg1?.alpha))add('Tarihsel alfa',pct(a.reg1.alpha),a.reg1.alpha>3?'positive':a.reg1.alpha< -3?'negative':'neutral','SPY günlük getirisine göre yıllıklandırılmış artık getiri.');
 if(Number.isFinite(a.volatility))add('Oynaklık',pct(a.volatility),a.volatility<20?'positive':a.volatility>35?'negative':'neutral','Günlük getirilerin yıllıklandırılmış standart sapması.');
 if(Number.isFinite(a.maxDrawdown))add('Maksimum düşüş',pct(a.maxDrawdown),a.maxDrawdown> -25?'positive':a.maxDrawdown< -45?'negative':'neutral','Gözlenen seride zirveden en derin düşüş.');
 if(profile?.assetClass==='equity'&&profile?.holdings?.length>=3){const weight=profile.holdings.slice(0,3).reduce((n,h)=>n+(h.weight||0),0);add('İlk 3 bileşen yoğunluğu',pct(weight),weight<20?'positive':weight>25?'negative':'neutral','Yalnızca doğrulanmış ve tarihli ilk üç bileşen; tüm portföyü ölçmez.');}
 const total=checks.reduce((n,x)=>n+(x.tone==='positive'?1:x.tone==='negative'?-1:0),0),label=checks.length<3?'Nötr':total>=2?'Pozitif':total<=-2?'Negatif':'Nötr',tone=label==='Pozitif'?'positive':label==='Negatif'?'negative':'neutral';
 return {checks,label,tone,summary:`${checks.length} ölçü birlikte değerlendirildi. Fonun fiyat ve risk görünümü ${label.toLocaleLowerCase('tr')}. Bileşen verisi yalnızca kaynak tarihi itibarıyla geçerlidir.`};
}
function etfScoreParts(a){
 const clamp=(v,n)=>Math.max(-n,Math.min(n,v));
 return [
  ['Başlangıç',50],['63 günlük momentum',Number.isFinite(a.momentum63)?clamp(a.momentum63*1.5,15):null],
  ['1 yıllık getiri',Number.isFinite(a.return1y)?clamp(a.return1y*.2,10):null],
  ['Oynaklık cezası',Number.isFinite(a.volatility)?-Math.max(0,a.volatility-25)*.25:null],
  ['Tarihsel alfa',Number.isFinite(a.reg1?.alpha)?clamp(a.reg1.alpha*.1,8):null],
 ];
}
function scoreTimeline(rows){
 if(rows.length<2)return '<p class="note">Skor geçmişi yeni kaydedilmeye başlandı. İkinci işlem günü oluştuğunda grafik görünecek.</p>';
 const series=rows.map(x=>({date:x.observed_date,close:x.score}));
 return lineChart([{name:'Skor',color:'#275ce7',history:series}],{height:190});
}
